const assert = require('node:assert/strict');
const { Ledger } = require('../.build/ledger');
const { PaymentService } = require('../.build/service');
const { Transient } = require('../.build/transport');
async function main() {
  const ledger = new Ledger(); const seen = [];
  let fail = 2;
  const svc = new PaymentService(ledger, { acknowledge: async r => { seen.push(r); if (fail-- > 0) throw new Transient('x'); } });
  const r = await svc.pay('t', 'k', 5);
  assert.equal(ledger.entries.length, 1); assert.equal(seen.length, 3);
  assert(seen.every(s => s === r));
  assert.deepEqual(await svc.pay('t', 'k', 5), r);
  await assert.rejects(svc.pay('t', 'k', 6), /key conflict/);
  assert.equal(ledger.entries.length, 1);
  await svc.pay('u', 'k', 6); assert.equal(ledger.entries.length, 2);
  const l2 = new Ledger(); const s2 = new PaymentService(l2, { acknowledge: async () => {} });
  const all = await Promise.all([1, 2, 3].map(() => s2.pay('a', 'b', 9)));
  assert.equal(l2.entries.length, 1); assert(all.every(x => x.id === 1));
  // exhaustion preserves last error; others not retried
  let calls = 0; const errs = [new Transient('1'), new Transient('2')];
  const s3 = new PaymentService(new Ledger(), { acknowledge: async () => { throw errs[calls++]; } });
  await assert.rejects(s3.pay('a', 'b', 1, 2), e => e === errs[1]); assert.equal(calls, 2);
  calls = 0; const s4 = new PaymentService(new Ledger(), { acknowledge: async () => { calls++; throw new Error('boom'); } });
  await assert.rejects(s4.pay('a', 'b', 1), /boom/); assert.equal(calls, 1);
  for (const a of [0, 6, 1.5, NaN]) {
    const l = new Ledger(); let c = 0;
    await assert.rejects(new PaymentService(l, { acknowledge: async () => { c++; } }).pay('a', 'b', 1, a), /invalid payment/);
    assert.equal(l.entries.length, 0); assert.equal(c, 0);
  }
}
module.exports = main();

